    {editingTemplate&&<OfficeEditor entry={{path:editingTemplate.name,name:editingTemplate.name,kind:'file',size:editingTemplate.file.size,modified:0}} repo={templateRepository(editingTemplate)} theme={theme} onClose={()=>{setEditingTemplate(undefined);setSettingsTab('configuration');setSettings(true);}} onSaved={()=>notify(`${templateLabel(editingTemplate)} template saved`)}/>}
